-- 5005 🏋️ Exercises from the book "goalkeeping-elite-training-program-60-proven-drills-ebook-vol-1" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'goalkeeping-elite-training-program-60-proven-drills-ebook-vol-1');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('GK jump patterns, catch and recovery save', 'warm_up', 'unopposed', NULL, 11, 11, 'Chapter 1 Warm-Ups: Drill 1', NULL, 'Warm-up agility, reactions and catching that ends with a recovery save to a small goal.', 'Main goal with a mannequin in front and a small goal off to one side; coach out front with balls, GK2 out wide.', 'Phase A: GK1 runs through jump patterns, catches a coach serve and rolls it back underarm. Phase B: GK1 hops back and side to side, steps up to catch a coach drop-kick or volley, rolls it back, then gets round the mannequin to save GK2''s shot at the small goal after the coach feeds GK2.', '8 repetitions', 'GK2 takes a touch forward first so GK1 has to rush out and block instead.', 'Drive jumps from the legs, not arm swing; slot light stretching or passing between sets to control load.', '2 GKs + coach', 3, 3, NULL, NULL, NULL, NULL, true, true, false, NULL, 10),
  ('Rope-jump catch circuit with distribution', 'warm_up', 'unopposed', NULL, 12, 12, 'Chapter 1 Warm-Ups: Drill 2', NULL, 'Reactive jumping and catching while tracking a second ball, finished with short distribution.', 'Three stations (A, B, C) on the edge of the box, each with a low rope/hurdle; coach serving, GK2 working opposite GK1.', 'A: coach volleys/drop-kicks, GK1 hops the rope to catch and throws back, then repeats on the far side vs GK2. B: GK1 rolls to the coach, coach feeds GK2, GK1 hops the rope to catch GK2''s shot and rolls it back. C: coach bounces a ball for GK1 to half-volley over the rope while GK2 throws a second ball to the coach.', '8 repetitions; phase C uses 2 balls at once', NULL, 'Delay the jump to mimic real reactions; land with feet about shoulder width; switch focus to the next ball at once.', '2 GKs + coach', 3, 3, NULL, NULL, NULL, NULL, true, true, false, NULL, 20),
  ('Post-touch, mannequin and save circuit', 'warm_up', 'unopposed', NULL, 13, 13, 'Chapter 1 Warm-Ups: Drill 3', NULL, 'Footwork, saves and handling with quick reactive catches in a four-phase circuit.', 'Goal(s) with a central mannequin; GK1 and GK2 in goal, GK3 and coach serving from in front at angles.', 'A: GK1 runs behind the mannequin and GK2 in front to touch opposite posts, then catch drop-kick/volley serves from GK3 and coach. B: keepers roll diagonally to the servers, touch the mannequin and save a low shot. C: roll diagonally then step up to block the server''s shot. D: touch the post then catch high throws.', '8 repetitions', NULL, 'Swap sides often to work both feet and both sides; GK1 always starts, GK2 follows straight after.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 30),
  ('Mannequin footwork with drop-kick catches', 'warm_up', 'unopposed', NULL, 14, 14, 'Chapter 1 Warm-Ups: Drill 4', NULL, 'Reactions, side-step footwork and handling against drop-kicks and low passes around mannequins.', 'Goal with two mannequins in front; coach out front with balls, GK2 out to the side.', 'A: GK1 throws to coach, moves round to catch a drop-kick in front of the mannequins, throws to GK2, shuffles back through the mannequins, touches the post and catches GK2''s drop-kick. B: GK1 rolls to GK2 and saves a low pass, throws to coach, touches the crossbar, then steps between the mannequins to catch the coach''s drop-kick.', '8 repetitions', NULL, 'Eyes on the ball always, never on the post or mannequin; side-step rather than cross-step over short distances.', '2 GKs + coach', 3, 3, NULL, NULL, NULL, NULL, true, true, false, NULL, 40),
  ('Hand-to-foot passing circle', 'warm_up', 'unopposed', NULL, 15, 15, 'Chapter 1 Warm-Ups: Drill 5', NULL, 'Coordination and passing with hands and feet in a tight group warm-up.', 'All keepers (three) and the coach stand in a small circle.', 'Each player controls the ball with one hand then passes with the foot to anyone in the circle.', 'Two touches: hand control then foot pass.', 'V1: control with one hand, pass with the opposite foot. V2: control with both hands before passing (e.g. right hand, left hand, then pass). V3: add a time or touch limit.', 'Quick reactions and accurate passing with both hands and both feet.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, false, true, false, NULL, 50),
  ('Colour-cone reaction sprint, turn and save', 'warm_up', 'unopposed', NULL, 16, 16, 'Chapter 1 Warm-Ups: Drill 6', NULL, 'Reacting to a visual cue, sprinting and turning efficiently into a save.', 'Goal with GK2 in it and two mannequins at the six-yard area; coloured cones in a line out front; GK3 with cones further out; coach to one side.', 'GK3 signals a colour by touching, raising or pointing at a cone; GK1 sprints to touch that colour and turns back; the coach passes to GK2; GK1 touches the mannequin on the matching side and sets to save GK2''s pass into the opposite corner.', '8 repetitions', NULL, 'React the moment the colour is clear; sprint straight and turn efficiently into the save; vary cone colours each round.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 60),
  ('Balance and contact strength challenges', 'warm_up', 'unopposed', NULL, 17, 17, 'Chapter 1 Warm-Ups: Drill 7', NULL, 'Explosive balance, body control and comfort with physical contact.', 'Pairs of keepers in small marked squares.', 'Series of short paired duels: on the ground shoulder to shoulder trying to stay balanced; in press-up position knocking the partner''s arm away; gripping right hands on one leg pulling the partner off balance; hopping with arms crossed trying to shoulder the partner out of the square. Stretch shoulders and legs between sets.', 'Explosive reps under 30 seconds each.', NULL, 'Builds bravery and composure in crowded boxes; pair keepers of similar weight.', 'pairs of GKs', 2, NULL, NULL, NULL, NULL, NULL, false, true, false, NULL, 70),
  ('Passing between mannequins with rotation', 'warm_up', 'unopposed', NULL, 18, 18, 'Chapter 1 Warm-Ups: Drill 8', NULL, 'Passing accuracy with both feet and footwork round mannequins.', 'Two mannequins at the edge of the six-yard box; GK1 between them, GK2 out to one side, coach central further out.', 'Coach passes between the mannequins to GK1, who plays diagonally to GK2; GK2 plays it back one-two; GK1 touches it out in front of the mannequin, moves behind and around it and passes back to the coach. GK1 and GK2 then swap.', '8 repetitions', NULL, 'Use both feet; firm, accurate passes and touches; rotate smoothly to keep the rhythm.', '2 GKs + coach', 3, 3, NULL, NULL, NULL, NULL, false, true, false, NULL, 80),
  ('First-time pass, strike and overhead throw sequence', 'warm_up', 'unopposed', NULL, 19, 19, 'Chapter 1 Warm-Ups: Drill 9', NULL, 'Combination passing with aerial handling and coordination.', 'Goal with two mannequins in the box; GK1 near them, coach out wide, GK2 in goal, GK3 out front.', 'GK1 rolls to the coach, who passes first time diagonally to GK2; GK2 strikes first time to GK3, who catches and throws overhead to GK1 as GK1 moves behind the mannequins to catch; repeat.', '8 repetitions', 'GK2 takes two touches to control and strike; GK1 steps out to block GK3 after GK2''s strike.', 'GK2 drives the ball through the air (adjust position if the coach''s pass is too firm); accelerate into position and watch the ball.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 90),
  ('Near-post receiving passing pattern', 'passing_unopposed', 'unopposed', NULL, 20, 20, 'Chapter 1 Warm-Ups: Drill 10a', NULL, 'Sharp passing and timing of movement to receive outside the near post.', 'Two mannequins near the box corner; GK2 wide near the post, GK1 central in the box, GK3 starting centrally further out between two poles.', 'GK2 passes towards the near post; GK1 moves across to receive outside it and passes diagonally between the mannequins to GK2. GK2 then plays towards the near post at the other end, where GK3 moves across to receive and passes back between the mannequins; continuous rotation.', '4 repetitions; two-touch (receive, pass).', NULL, 'Call for the ball before it arrives; GK2 judges the pass weight since he plays one touch.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, false, true, false, NULL, 100),
  ('One-touch lay-off and switch to the far post', 'passing_unopposed', 'unopposed', NULL, 21, 21, 'Chapter 1 Warm-Ups: Drill 10b', NULL, 'One-touch build-up, lay-off timing and receiving to the side of the goal.', 'As Drill 10a: two mannequins, GK1 by the far post, GK2 wide, GK3 starting centrally further out.', 'GK1 passes diagonally through the mannequins to GK2, who lays it off outside the post; GK3 moves across to receive (first touch) and switches play with his second touch to GK1 at the opposite post; continuous rotation.', '4 repetitions', NULL, 'GK1''s pass must be soft enough to lay off first time; GK3 times his run to the lay-off.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, false, true, false, NULL, 110),
  ('Box build-up combination ending in a low shot', 'passing_unopposed', 'unopposed', NULL, 22, 22, 'Chapter 1 Warm-Ups: Drill 10c', NULL, 'Build-up passing combinations finishing with an accurate low shot for the keeper to save.', 'Goal with a target corner marked; two mannequins; GK1 in goal, GK2 wide, GK3 central further out.', 'GK1 throws overarm to GK3, who rolls through the mannequins to GK2; GK2 plays to the near post for GK1 to receive and switch to GK3 at the far side; GK3 touches forward and passes through the mannequins to GK2, who sets back; GK3 shoots low into the target corner and GK1 saves.', '4 repetitions', NULL, NULL, '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, false, NULL, 120),
  ('Tennis-racket reaction catches and throw', 'warm_up', 'unopposed', NULL, 23, 23, 'Chapter 1 Warm-Ups: Drill 11', NULL, 'Reaction catching, quick decisions and fast distribution using tennis balls.', 'Goal with two mannequins; GK1 in goal, GK2 to the side in the box, coach out front with a racket and GK3 holding a box of tennis balls.', 'Coach hits tennis balls at GK1, either underarm for a high ball or overarm for a low bouncing ball; GK1 catches and immediately throws to GK2. Rotate keepers after a set number.', '8 repetitions', NULL, 'Stay light on the feet and react to the trajectory; catch cleanly before releasing.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 130),
  ('Post sprint, mannequin footwork and catches', 'goalkeeping', 'unopposed', NULL, 25, 25, 'Chapter 2 Technical: Drill 1', NULL, 'Quick technical footwork, movement and catching.', 'Goal with two mannequins in front; GK1 central in goal; GK2 and GK4 wide at each post, GK3 out front.', 'From the middle of the goal GK1 sprints to a post, moves inside to catch GK2''s overarm throw, returns it and touches the far mannequin; catches GK3''s throw, goes round the near mannequin and touches the far one; finishes by catching GK4''s throw.', '10 repetitions', 'Coach signals with a hand where GK1 must move to catch.', 'Thumbs together in a W; spread fingers to absorb; stay light and fast with eyes on the ball.', '4 GKs (+coach for variation)', 4, 5, NULL, NULL, NULL, NULL, true, true, false, NULL, 140),
  ('Block then recover to catch the rebound', 'goalkeeping', 'passive', NULL, 26, 26, 'Chapter 2 Technical: Drill 2', NULL, 'Fast closing down, blocking technique and a quick second action.', 'Mannequins around the edge of the box; GK1 near one, GK2 to the side, GK3 further away.', 'GK1 rolls past the mannequin to GK2, who passes across first time to GK3; GK3 ''shoots'' and GK1 dives with both hands to block; if the block reaches GK3, GK1 gets up to catch GK3''s return throw.', '8 repetitions', NULL, 'Close GK3 down quickly and aggressively; small steps when attacking with the hands; lead with the right leg to shut the goal; eyes on the ball.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, false, true, false, NULL, 150),
  ('High ball timing and controlled punching', 'goalkeeping', 'unopposed', NULL, 27, 27, 'Chapter 2 Technical: Drill 3', NULL, 'Timing on high balls and punching technique, plus catching crosses.', 'Two goals (A and B) with mannequins in front; coach and keepers serving from the sides.', 'A: GK2 throws to the coach, who serves high between the mannequins; GK1 steps forward and punches it over the goal to GK3, who catches and throws on to GK2. B: coach throws a short high ball, GK1 punches it left-handed over the goal to GK3; GK3 rolls to GK2, GK2 passes back and GK3 crosses for GK1 to catch high.', '10 repetitions', NULL, 'Use both hands, alternate; punch at chest height; let the ball travel slightly past before punching; short explosive punch; call early.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 160),
  ('Falling saves either side of a mannequin', 'goalkeeping', 'unopposed', NULL, 28, 28, 'Chapter 2 Technical: Drill 4', NULL, 'Explosive low falling saves, recovery and reset.', 'Goal with two mannequins in the box; GK1 behind one; GK2, GK3 and GK4 around the area.', 'GK1 passes to GK2, who drives a low pass/shot into the far corner of the mannequins for a falling save; GK1 rolls to GK3, GK3 passes to GK4 as GK1 moves behind the nearest mannequin; GK4 shoots low to the far corner and GK1 makes a second falling save. All rotate positions.', '6 repetitions; keepers rotate GK1 to GK4.', NULL, 'Start behind the mannequin to arrive in front with power; always fall forward to the ball; server mirrors GK1''s line; alternate save side.', '4 GKs', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 170),
  ('Kicking variations with two-ball reaction saves', 'goalkeeping', 'unopposed', NULL, 29, 29, 'Chapter 2 Technical: Drill 5', NULL, 'Kicking technique variety (volley, pass, header) with reaction saves and handling.', 'Three circuits each with a goal and two mannequins, a coach beside the goal and two keepers out front around the six-yard line.', 'Two balls are live in each circuit. A: coach throws to GK2, who volleys into GK1''s hands between mannequin and post; GK1 throws to GK3, who throws to the coach. B: coach passes to GK2, who passes into GK1''s hands; GK1 rolls to GK3, who passes to the coach. C: coach throws high and GK2 heads into GK1''s hands; GK1 throws to GK3, who catches and throws to the coach.', '8 reps per player per circuit; always 2 balls at once.', 'Variations A, B and C as listed.', 'Aim for 8 clean catches; GK2 attacks the catch under pressure; eyes on the next ball immediately; head with a straight contact.', '3 GKs + coach per circuit', 4, NULL, NULL, NULL, NULL, NULL, true, true, false, NULL, 180),
  ('Close down and block close-range shots', 'goalkeeping', 'passive', NULL, 31, 31, 'Chapter 2 Technical: Drill 6', NULL, 'Reactive shot blocking and narrowing the angle for close-range saves.', 'Mannequins spread around the edge of the box; GK1 near a mannequin, coach in front with GK2 and GK3 either side.', 'GK1 rolls to the coach, who passes in front of GK2 or GK3; GK1 closes that player down quickly and dives with both hands to block the ''shot''.', '4 repetitions', 'Coach passes closer to the receiver''s feet, so GK1 narrows the angle and drops into the ''Block Position'' (kneeling block) to stop a close-range shot.', 'Fast, aggressive approach; minimal steps before diving; lead with the right leg to shut the angle; watch the ball throughout.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, false, true, false, NULL, 190),
  ('Long throws and long passing accuracy', 'goalkeeping', 'unopposed', NULL, 32, 32, 'Chapter 2 Technical: Drill 7', NULL, 'Long overarm throws and long aerial passing with control and reset.', 'Goal with coach and GK2 at the six-yard area; GK3 midway; GK4 at the centre circle between two mannequins; GK1 starting near goal.', 'Coach throws high for GK2 to jump and catch; GK2 throws long overarm to GK4, who chests it down and passes to GK3; GK4 moves round a mannequin to take GK3''s lay-off and hits a long aerial pass into the box for GK1, who jumps to catch and throws to the coach.', '8 repetitions', NULL, 'Straight, controlled throw keeping one arm up and following through over the head; long kick with the stronger foot; start closer if distances are too big; stronger keepers practise the weaker foot.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, false, true, false, NULL, 200),
  ('One-touch passing square with rotation', 'passing_unopposed', 'unopposed', NULL, 33, 33, 'Chapter 2 Technical: Drill 8', NULL, 'One-touch distribution accuracy and rotating through positions.', 'Two keepers on the six-yard line, two further out by mannequins, cones in the middle forming a square/diamond.', 'One ball: GK1 plays straight to GK4, GK4 diagonally to GK2, GK2 straight to GK3, GK3 diagonally to GK1. Two balls: start with balls at GK1 and GK2 played simultaneously straight then diagonal.', '8 repetitions; all passes one touch; after two full cycles everyone rotates one position clockwise.', '1-ball version, then 2-ball version.', NULL, '4 GKs', 4, 4, NULL, NULL, NULL, NULL, false, true, false, NULL, 210),
  ('High catch then recovery to low falling save', 'goalkeeping', 'unopposed', NULL, 34, 34, 'Chapter 2 Technical: Drill 9', NULL, 'High catching followed by fast footwork to make a low falling save.', 'Two parallel stations by the six-yard box, each with a mannequin and a blue cone; GK1/GK3 working, GK2/GK4 serving.', 'GK1/GK3 throw to GK2/GK4, who push the ball up with both hands for a high catch; the ball is rolled back, then the working keeper moves quickly round the mannequin and saves a low pass/shot played between mannequin and cone into the chest with two hands.', '8 repetitions', 'GK1/GK3 throw the high balls themselves; GK2/GK4 start with the ball and roll it for a low falling dive.', 'Quick footwork, eyes on the ball; start behind the mannequin or cone so you attack the ball as you fall.', '4 GKs', 4, 4, NULL, NULL, NULL, NULL, false, true, false, NULL, 220),
  ('Drop-kick catch then block and loose-ball recovery', 'goalkeeping', 'passive', NULL, 35, 35, 'Chapter 2 Technical: Drill 10', NULL, 'Quick reactions, getting set in the Block Position and securing the loose ball.', 'Goal with a mannequin at the near post and one in the box; coach out front; GK2 and GK3 on the side of the box.', 'GK1 touches the mannequin and catches the coach''s drop-kick; GK1 rolls to the coach, who passes to GK2; GK2 plays to GK3 and GK1 times his move off the goal to close GK3 down in the Block Position; after the block GK1 recovers at once to win the loose ball.', '6 repetitions', NULL, 'Eyes on the ball when moving to the mannequin; approach quickly but arrive balanced; close the shortest route to goal, legs closed.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 230),
  ('Header back, backpedal to catch long ball', 'goalkeeping', 'unopposed', NULL, 36, 36, 'Chapter 2 Technical: Drill 11', NULL, 'Backpedalling recovery to deal with a ball over the head, plus long distribution.', 'Goal with a second small goal on the edge of the box; coach behind it; GK2 at the main goal; GK3 and GK4 further out.', 'Coach feeds the ball over the small goal and GK1 heads it back; GK1 then backpedals towards the main goal and catches a long ball from GK4 while GK2 steps into GK1''s old spot; GK1 rolls to GK3, who rolls on to GK4. GK1 and GK2 swap roles.', '6 repetitions', NULL, 'Head the ball with eyes open and head straight; start the backpedal with a cross step; turn back towards the first post to cover most goal.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, true, true, false, NULL, 240),
  ('Passing and support sequence through mannequins', 'passing_unopposed', 'unopposed', NULL, 38, 38, 'Chapter 3 Passing: Drill 1', NULL, 'Passing and support movement with timing, both feet and scanning.', 'Goal with GK1 in the six-yard box, GK2 wide at the box edge, GK3 near the D; two mannequins and cones near the top of the box.', 'Set passing rotations: GK2 to GK1 to GK3 through the cone and mannequin; GK3 to GK2 to GK3 through the mannequins to GK1 beside the six-yard box; GK1 to GK2 back to GK1 to GK3; GK3 to GK2 to GK3 to GK1 to GK2 to restart.', '8 repetitions', NULL, 'Sharp, direct passes; GK1 calls early and receives with an open body; use both feet; scan after every touch.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, false, true, false, NULL, 250),
  ('Double one-two, lofted ball catch and call', 'passing_unopposed', 'unopposed', NULL, 39, 39, 'Chapter 3 Passing: Drill 2', NULL, 'Combination passing, catching a lofted ball and communication under pressure.', 'Main goal with mannequins and a small goal on the edge of the box; GK1 in goal, GK2 and GK3 at the box, coach and GK4 on the far side.', 'GK2 plays into space for GK3, who plays a double one-two with GK1; GK1 passes diagonally to GK2, who controls and passes to the coach (2 touches); the coach sets for GK4 to loft the ball over the small goal for GK1 to catch, and GK1 rolls to GK2 to restart.', '6 repetitions', NULL, 'Call early as the ball travels to GK3; shout before the cross comes over; if not catching, shout ''YOU'' so defenders know.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, true, true, false, NULL, 260),
  ('Goal-kick recovery movement and cut-back save', 'goalkeeping', 'unopposed', NULL, 40, 40, 'Chapter 3 Passing: Drill 3', NULL, 'Distribution, recovery movement to get open and positioning for a cut-back.', 'Goal with GK1 in the six-yard box; coach wide; two mannequins; GK2 at the box edge; GK3 wide near the byline.', 'GK1 passes to the coach, moves back to create space and receives the return; GK1 passes between the mannequins to GK2, who plays diagonally to GK3; GK3 makes a deep run and cuts the ball back to GK1 for a finish or a save.', '4 repetitions', NULL, 'After the first pass drop back to make space and distance as if under pressure; open the hand and call ''HERE''; ask for the ball on the side away from goal; don''t touch the post while waiting for the cut-back.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, false, NULL, 270),
  ('GK passing flow and timing triangle', 'goalkeeping', 'unopposed', NULL, 41, 41, 'Chapter 3: Drill 4a', 'Maarten Arts', 'Accurate ground passing, scanning and timed movement into space for keepers.', 'One goal; two mannequins on the edge of the box; GK1 near the goal line, GK2 and GK3 out in front.', 'Three keepers keep a continuous passing sequence: give-and-goes into space, diagonal returns, a pass threaded between the mannequins and a one-two before the ball goes back to GK1 to restart.', '6 repetitions', NULL, 'Do not overhit; every pass goes straight into a precise spot. Each keeper calls for the ball loudly.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 280),
  ('Passing pattern ending in far-post save', 'goalkeeping', 'unopposed', NULL, 42, 42, 'Chapter 3: Drill 4b', 'Maarten Arts', 'Combines a keepers'' passing pattern with a shot-stopping action and short distribution.', 'Same set-up as Drill 4a: one goal, two mannequins, three keepers.', 'Keepers run the passing pattern, then GK3 shoots inside the far post for GK1 to save; GK1 rolls the ball between the mannequins for GK2, who drops to receive, and play returns to GK1.', '6 repetitions', 'Variation of Drill 4a with a save added', 'Passes not too fast and into precise spots; call for every ball.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 290),
  ('Long lofted pass, high catch and save', 'goalkeeping', 'unopposed', NULL, 43, 43, 'Chapter 3: Drill 5', 'Maarten Arts', 'Long lofted kicking, aerial catching and shot-stopping in one sequence.', 'Two goals facing each other across the box area, mannequins near the main goal; GK1 in goal, GK2 in front, GK3 far out near the centre circle, coach to the side.', 'GK2 sets the ball back for GK1 to loft over the second goal to GK3; GK3 controls and kicks a high ball back for GK1 to catch; GK1 rolls to the coach who feeds GK2, who strikes at goal for GK1 to save.', '4 repetitions; GK3 two touches', NULL, 'Use both feet for lofted passes; quick footwork to set for the shot; clean control of the long ball.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 300),
  ('Lofted distribution and cross catch rotation', 'goalkeeping', 'unopposed', NULL, 44, 44, 'Chapter 3: Drill 6', 'Maarten Arts', 'Lofted passing under pressure, scanning before receiving and catching a delivered cross.', 'Main goal with mannequins either side of the 6-yard box, a spare goal inside the box, a small goal wide right; GK1 in goal, GK2 and GK3 on the left, GK4 and coach on the right.', 'Part 1: GK1, GK2 and GK3 combine before GK2 lofts the ball over the spare goal to GK4. Part 2: GK4 plays a one-two with the coach and lofts a cross into the 6-yard box between the mannequins for GK1 to catch.', '3 repetitions; two touches on receiving', NULL, 'GK1 scans the far side and opens his body before asking for the back pass; GK2 takes a directional touch before the loft; GK1 drops beyond the spare goal before the cross.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, true, true, true, NULL, 310),
  ('Third-man run and cut-back saves', 'goalkeeping', 'unopposed', NULL, 45, 45, 'Chapter 3: Drill 7', 'Maarten Arts', 'One-touch passing with third-man timing, finished by saves from cut-backs.', 'Two goals facing each other across the box, a mannequin and cones; coach out wide with cones, GK1 central, GK2 near the far post, GK3 in the second goal.', 'GK1 rolls to GK2 who passes through cones to the coach; coach plays a one-two with GK1 then cuts back for GK3 to save. Then GK3 rolls to GK1, GK1 sets GK3 towards the opposite post, GK3 finds GK2 who cuts back for GK1 to save.', '4 repetitions', NULL, 'One-touch passes into the receiver''s path at a high level; do not move into position too early, time the movement before the shot; keepers may invent their own patterns in the same structure.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 320),
  ('Distribution circuit: volley, loft, underarm', 'goalkeeping', 'unopposed', NULL, 46, 46, 'Chapter 3: Drill 8', 'Maarten Arts', 'Varied distribution technique: volleys, lofted passes, rolls and underarm throws.', 'Main goal with two small goals either side in the box; GK1 in goal, GK3 and GK4 by the side goals, GK2 out in front.', 'GK2 volleys to GK1, who rolls to GK3; GK3 lofts to GK4; GK4 rolls to GK1 who passes back to GK4; GK4 lofts to GK3; GK3 throws underarm to GK2 and the circuit repeats.', '4 repetitions', 'Add a second ball to raise the speed', 'Every pass clean and accurate; use both feet; keep quality high when speed rises.', '4 GKs', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 330),
  ('Goal kick, exchange and lofted pass', 'goalkeeping', 'unopposed', NULL, 47, 47, 'Chapter 3: Drill 9', 'Maarten Arts', 'Lofted distribution, short exchanges and scanning for new passing options.', 'Main goal with mannequins, a second goal in front; GK1 near main goal, GK2 to the left, GK3 far out; coach to the side.', 'GK1 and GK2 exchange passes before GK1 lofts over the goal towards GK3; GK3 controls, plays a one-two with GK2 and lofts the ball back for GK1 to catch between the end goal and the mannequins.', '6 repetitions; GK3 two touches', NULL, 'GK1 drops quickly after the kick to make space; scan the opposite side after passing; balance with the opposite arm when kicking with the weaker foot; approach the ball from a wide angle.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 340),
  ('Lofted catch, quick save and lofted return', 'goalkeeping', 'unopposed', NULL, 48, 48, 'Chapter 3: Drill 10', 'Maarten Arts', 'Catching a lofted ball, reacting to a quick shot and lofted distribution.', 'Main goal with mannequins and two small goals beside, a second goal in front; GK1 in main goal, coach and GK2 near it, GK3 far out.', 'GK3 lofts over the goal to GK1 who catches and rolls to the coach; coach feeds GK2 who shoots between mannequins to the far post for a quick save; GK1 rolls to the coach, gets the ball back through the mannequins and passes for GK2 to loft over the goal to GK3.', '6 repetitions', NULL, 'GK3 calls before the ball crosses the goal; GK1 and GK2 call clearly from outside their goal.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 350),
  ('Tennis-racket turn and catch reactions', 'goalkeeping', 'unopposed', NULL, 50, 50, 'Chapter 4: Drill 1', 'Maarten Arts', 'Reaction catching after turning, from three different feeding positions.', 'Goal with mannequins and cones in the box; coach with tennis racket and balls at one of three positions, GK3 holding the ball box, GK2 wide.', 'GK1 faces his goal, turns on the coach''s call and tries to catch a tennis ball hit with a racket; if he catches it he throws a ball to GK2, otherwise he makes a save; he resets facing the goal. Repeat from all three positions.', '10 reps per position', NULL, 'Stay light on the feet and react to different trajectories; clean catching technique before releasing.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 360),
  ('Low bounce saves stepping back to goal', 'goalkeeping', 'unopposed', NULL, 51, 51, 'Chapter 4: Drill 2', 'Maarten Arts', 'Reaction saves on low bouncing balls while reading the change in distance to goal.', 'Goal with two mannequins on the 6-yard line; coach with tennis racket out front, GK3 holding the ball box, GK2 to the side.', 'Coach hits low bouncing tennis balls at GK1, who starts saving in front of the mannequins and gradually steps back towards goal; any catch is thrown straight to GK2.', '20 repetitions', NULL, 'Feeder supplies balls quickly; aim to catch every ball; reset fast for the next ball.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 370),
  ('Multi-angle saves with volley distribution', 'goalkeeping', 'unopposed', NULL, 52, 52, 'Chapter 4: Drill 3', 'Maarten Arts', 'Saves from several angles, recovery movement and volley/rolled distribution.', 'Goal with mannequins in and around the box; coach on the left edge, GK2 right, GK3 out front.', 'Coach volleys to GK1, who saves and throws to GK2; GK2 volleys back; GK1 rolls to the coach, receives again and passes to GK3, who takes a directional touch and cuts the ball back inside the mannequin; GK1 saves and throws to the coach to restart.', '6 repetitions', NULL, 'Move quickly between actions keeping catching and positioning quality; arrive just before shots or crosses; reset centrally after releasing.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 380),
  ('High tempo reaction chain', 'goalkeeping', 'unopposed', NULL, 53, 53, 'Chapter 4: Drill 4', 'Maarten Arts', 'Action-after-action saving, catching and recovering under pressure.', 'Goal with mannequins and a cone in the box; two coach positions on the left, GK2 in front, GK3 on the right.', 'Coach throws high for GK1 to catch; GK1 rolls to GK2 and saves GK2''s shot, rolls to GK3 and saves GK3''s shot, gets up and throws to the coach; GK1 shifts across to save from the coach and rolls to GK3; GK3 passes to GK2 while GK1 moves between mannequin and cone to block GK2''s shot.', '3 repetitions', NULL, 'Go action after action without overthinking; coach judges performance under pressure; servers stay focused and give quality service.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 390),
  ('Repositioning to multiple passing positions', 'goalkeeping', 'unopposed', NULL, 54, 54, 'Chapter 4: Drill 5a', 'Maarten Arts', 'Positional awareness: re-adjusting to every ball position as if a shot could come.', 'Goal; two mannequins near the D; GK2 central, GK3 right, GK4 left, coach at the D.', 'GK1 rolls through GK2''s legs; GK2 spins and exchanges with the coach; coach plays into space for GK3 who passes across to GK4; GK4 plays back to GK2, who has run round a mannequin, and GK2 shoots for GK1 to save.', '4 repetitions', NULL, 'Reposition for every ball location (coach, GK2, GK3, GK4); keep ball speed controlled so every pass is clean.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, true, true, true, NULL, 400),
  ('Repositioning with aerial pass into shot', 'goalkeeping', 'unopposed', NULL, 55, 55, 'Chapter 4: Drill 5b', 'Maarten Arts', 'Repositioning plus controlling an aerial pass before the final shot.', 'Same set-up as Drill 5a.', 'GK1 rolls through GK2''s legs, GK2 exchanges with the coach; coach plays to GK4 who lofts across to GK3; GK3 chest-controls and passes to GK2, who has run round the mannequin and shoots for GK1 to save.', '4 repetitions', 'Variation of Drill 5a with an aerial pass', 'Treat every ball source as a live threat; GK3 controls cleanly; GK2 sets body shape early; lofted ball high enough to pressure but controllable.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, true, true, true, NULL, 410),
  ('High catch, 360 recovery and near-post save', 'goalkeeping', 'unopposed', NULL, 56, 56, 'Chapter 4: Drill 6', 'Maarten Arts', 'High catching, footwork round a mannequin and near-post shot-stopping.', 'Goal with two mannequins on the 6-yard line; coach at the left of the goal, GK3 left edge of box, GK2 right.', 'GK1 catches a high ball through the mannequins and throws to GK2, who volleys back; GK1 catches, rolls to the coach and runs around the furthest mannequin; GK3 receives from the coach and strikes at the near post for GK1 to save.', '4 repetitions', NULL, 'Hands stay in front of the body when circling the mannequin; stay relaxed, one step at a time; consistent technique over speed.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 420),
  ('Positional adjustment with high catch recovery', 'goalkeeping', 'unopposed', NULL, 57, 57, 'Chapter 4: Drill 7', 'Maarten Arts', 'Repositioning between low saves and high catches.', 'Goal with mannequins in the box; GK3 near left post area, GK2 left of the box, coach far out right.', 'GK1 high catches next to a mannequin, rolls to GK2 and runs round the mannequin; GK2 passes to GK3 who strikes for GK1 to save; GK1 throws back to GK2, then moves behind the central mannequin to catch the coach''s volley.', '6 repetitions', NULL, 'Shout as soon as the ball leaves GK3''s foot; wait and time the move for the low ball; stay light and quick in transition.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 430),
  ('Short corner coverage and positional play', 'goalkeeping', 'unopposed', NULL, 58, 58, 'Chapter 4: Drill 8', 'Maarten Arts', 'Following the ball''s path and covering the short post.', 'Goal; two mannequins near the edge of the box; GK2 central, GK3 to the left.', 'GK1 throws to GK2, who volleys back; GK1 rolls into space for GK2 who passes across to GK3; GK3 runs on and strikes at GK1, who catches and throws back to GK3 at the edge of the box. Sequence repeats in the opposite direction.', '6 repetitions', 'Variation: GK3 strikes low balls either side of GK1', 'Follow the ball''s path, ready for a shot after GK2''s low pass; always check the short post position.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 440),
  ('Continuous saves, footwork and long throws', 'goalkeeping', 'unopposed', NULL, 59, 59, 'Chapter 4: Drill 9', 'Maarten Arts', 'Continuous saving with footwork round a mannequin and long throws.', 'Goal with mannequins in the box; GK2 out front, GK3 behind/beside the goal.', 'GK2 drop-kicks to GK1 who catches and rolls back; GK2 side-foots to the corner while GK1 moves behind the mannequin to dive; GK1 throws over the goal to GK3, runs round the mannequin, touches the post and circles to the far side; GK3 throws over the goal to GK1 who returns it; GK3 rolls to GK2 who passes for GK1 to save.', '4 repetitions', NULL, 'Focus and reset quickly; face out to the pitch when circling; land on two feet before diving sideways for the last ball.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 450),
  ('Low saves, recovery and 1v1 block', 'goalkeeping', 'unopposed', NULL, 60, 60, 'Chapter 4: Drill 10', 'Maarten Arts', 'Low saves, recovery saves and 1v1 blocking with dynamic positioning.', 'Goal with mannequins in the box; GK2 left, GK3 left out front, coach far right.', 'GK1 rolls to GK2, who passes inside the mannequin for GK1 to save; GK1 rolls to the corner of the 6-yard box and moves across to save the coach''s drop-kick; GK2 passes to GK3 who either shoots for the far corner or dribbles in for GK1 to block 1v1.', '3 repetitions', NULL, 'One action at a time; cross-step to reset for the coach''s shot; choose a starting position that allows pressure and recovery in the 1v1.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 460),
  ('Parry control and short recovery', 'goalkeeping', 'unopposed', NULL, 61, 61, 'Chapter 4: Drill 11', 'Maarten Arts', 'Quick steps, saving from throws and parrying into a safe area.', 'Goal with a mannequin near the post and another in the box; coach in front with balls, GK2 left of goal, GK3 left edge.', 'GK1 starts a yard from the mannequin, touches it, moves to save the coach''s throw and throws back; repeat three times. Then GK2 throws towards the mannequin and GK1 parries the ball to GK3.', '4 repetitions', NULL, 'Quick steps to the mannequin with eyes on the ball; stay near the line before attacking the save; deflect the last ball with the upper arm into GK3''s hands.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 470),
  ('Ground crosses with timed saves', 'goalkeeping', 'unopposed', NULL, 62, 62, 'Chapter 4: Drill 12', 'Maarten Arts', 'Positional adjustment and timing against ground crosses from both sides.', 'Goal with mannequins and cones in the box; coach at the edge of the box, GK2 right, GK3 left.', 'Coach plays into space for GK2 to cut back a ground cross; GK1 saves and rolls back. Coach then plays for GK3 to dribble and cut back from the other side; GK1 saves and rolls back.', '4 repetitions', NULL, 'Time the approach without overcommitting; stay low and forward, leading with the hands; reset quickly between sides.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 480),
  ('Cone touch, lateral move and ground save', 'goalkeeping', 'unopposed', NULL, 64, 64, 'Chapter 5: Drill 1a', 'Maarten Arts', 'Fast lateral footwork across goal into a ground save.', 'Goal with a cone just off each post area; GK2 in front at the 6-yard area with balls supplied by GK3.', 'GK1 touches the cone, moves quickly across the goal and saves GK2''s ground pass/shot; GK3 feeds the next ball to GK2.', '6 repetitions; GK2 misses the target = 5 push-ups', NULL, 'Start close to the line and attack the ball from there; shoulders over knees on contact; keep the trailing foot anchored when falling; GK2 must aim between post and cone.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 490),
  ('One-two then far-post save', 'goalkeeping', 'unopposed', NULL, 65, 65, 'Chapter 5: Drill 1b', 'Maarten Arts', 'Tracking the ball through a combination and saving at the far post.', 'Goal; two mannequins outside the box on the left; GK2 and GK3 out to the left.', 'GK1 rolls the ball between the mannequins to GK2, who plays a one-two with GK3 and shoots for the far post for GK1 to save.', '6 repetitions; GK2 misses or fails to test the far post = 5 push-ups', NULL, 'Track the ball early through the mannequins and adjust body shape; quick lateral footwork, no sliding or leaning early; GK2 aims precisely; clean, well-timed return pass.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 500),
  ('Lofted pass build-up into assisted shot', 'goalkeeping', 'unopposed', NULL, 66, 66, 'Chapter 5: Drill 2', 'Maarten Arts', 'Lofted kicking over a target goal followed by a save from a set-up shot.', 'Main goal and a second goal at the edge of the box; GK2 far out right, coach near the D, GK3 left.', 'GK1 lofts the ball over the second goal to GK2, who controls and passes to the coach in two touches; the coach sets the ball for GK3 to shoot and GK1 saves.', '4 repetitions; GK2 two touches', NULL, 'The goal is a clear visual target for high balls; for younger players lay the goal on its side to shorten the distance; a small cone to place the ball helps technique, especially the weaker foot.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 510),
  ('Back pass pressure and angled shot save', 'goalkeeping', 'unopposed', NULL, 67, 67, 'Chapter 5: Drill 3', 'Maarten Arts', 'Handling a back pass, then repositioning to save an angled shot.', 'Goal with mannequins in the 6-yard area; GK2 at a cone near the D, GK3 out left.', 'GK1 passes to GK2, who sprints forward from the cone like a recovering centre back and returns it to GK1 at the 6-yard box corner; GK1 passes to GK3, who plays into space for GK2 to receive at an angle; GK2 takes a forward touch and shoots low to the near or far corner for GK1 to save.', '6 repetitions', NULL, 'Return pass soft enough for GK1 to play first time; GK2''s touch before shooting goes forward, not sideways.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 520),
  ('Recovery save across goal after sprint', 'goalkeeping', 'unopposed', NULL, 68, 68, 'Chapter 5: Drill 4', 'Maarten Arts', 'Recovering across the goal for saves and reacting after a sprint.', 'Main goal with a side goal at the right of the box, mannequins and a cone; GK2 at the side goal, GK3 left.', 'GK2 rolls to GK3 who passes to GK1, who moves across the goal and passes to GK2; GK1 recovers to save GK2''s shot. GK1 rolls to GK3, who shoots low into the corner of the side goal while GK2 sprints round a cone and dives to save.', '6 repetitions', NULL, 'Call for the ball as soon as the drill starts; use a cross-step to recover on the return save; GK2 gets back to the line quickly, feet aligned, before the last shot.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 530),
  ('Positional passing into near-post save', 'goalkeeping', 'unopposed', NULL, 69, 69, 'Chapter 5: Drill 5', 'Maarten Arts', 'Adjusting position after every pass and saving a near-post shot.', 'Goal with mannequins; coach central, GK2 at the D on the left, GK3 to the right near a cone.', 'GK1 rolls to GK2, who plays a one-two with the coach and passes into space for GK3 to run onto; GK3 shoots to the near post for GK1 to save.', '6 repetitions; rotate every 6 balls', NULL, 'Adjust position after every pass; GK3 varies shots (inside, outside, instep); rotate positions every 6 balls.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 540),
  ('Angle save recovery with timed repetitions', 'goalkeeping', 'unopposed', NULL, 70, 70, 'Chapter 5: Drill 6', 'Maarten Arts', 'Timing the step into position for angled shots from both sides.', 'Two goals facing each other, a mannequin and cones; GK3 at the left of the far goal, coach central, GK4 at the right, GK2 in the near goal.', 'GK3 plays a one-two with the coach and shoots towards the near post; GK2 touches the mannequin, saves and rolls to GK4; the sequence repeats from the other side starting with GK4.', '4 repetitions', 'Variations: touch the mannequin first; or touch the near post and save at the far post', 'Delay the step into position so you arrive just before the shot; alternate sides; be confident with both feet at this distance.', '4 GKs + coach', 5, 5, NULL, NULL, NULL, NULL, true, true, true, NULL, 550),
  ('Timed forward step for far-post shot', 'goalkeeping', 'unopposed', NULL, 71, 71, 'Chapter 5: Drill 7a', 'Maarten Arts', 'Timing the forward movement and body shape to save a far-post shot.', 'Goal with two mannequins outside the 6-yard box; GK2 at the right post, coach left at the D, GK3 right with a cone.', 'GK1 rolls to GK2, who passes through the mannequins to the coach; the coach plays first time into space for GK3, who shoots for the far post and GK1 saves.', '6 repetitions', NULL, 'Be ready to react straight away to the shot; at the near post orient the body to track the play; attack the space once the shot is struck.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 560),
  ('Coming out for a close-range block', 'goalkeeping', 'unopposed', NULL, 72, 72, 'Chapter 5: Drill 7b', 'Maarten Arts', 'Narrowing the angle and using the block position against a dribbler.', 'Same set-up as Drill 7a.', 'GK1 rolls to GK2, who passes through the mannequins to the coach; the coach plays into space for GK3, who exchanges a one-two with GK1 then dribbles at goal; GK1 comes out, narrows the angle and blocks in the block position.', '6 repetitions', 'Combination variation 2 of Drill 7a', 'Time the approach and be set before contact; hands and body compact; stay balanced and do not dive early, make the attacker move first.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 570),
  ('Late signal target shot competition', 'goalkeeping', 'unopposed', NULL, 73, 73, 'Chapter 5: Drill 8', 'Maarten Arts', 'Reactive footwork and decision-making when the shooter learns the target late.', 'Main goal and a second goal at right angles on the right of the box, an elastic rope, cones; GK3 starts at a cone in the box, coach by the post.', 'GK3 runs round a cone and side-foots a ground shot, alternating near post and far post at GK1 and GK2 in the two goals over four balls; the coach signals the target only just before GK3 receives.', '4 repetitions; keeper with most saves wins', NULL, 'Late target creates a decision and reaction challenge; competition: the keeper with most saves wins.', '3 GKs + coach', 4, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 580),
  ('Combinations into low and high corner saves', 'goalkeeping', 'unopposed', NULL, 74, 74, 'Chapter 5: Drill 9', 'Maarten Arts', 'Saving low and high corner shots after quick passing combinations.', 'Goal with mannequins in and outside the box; GK2 left, coach central.', 'GK1 rolls to GK2 and they play a one-two between the mannequins; GK2 plays a one-two with the coach around a mannequin and strikes at goal: low into the corner on the first rep, high into the top corner on the second.', '6 repetitions', NULL, 'Move and pass at high speed; GK1 rolls back to GK2 straight after the save; check the post to confirm position.', '3 GKs + coach', 3, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 590),
  ('Two-ball reactive shot sequence', 'goalkeeping', 'unopposed', NULL, 75, 75, 'Chapter 5: Drill 10', 'Maarten Arts', 'Mental sharpness handling a fast chain of catches, throws and a near-post save.', 'Goal with a cone; mannequins on the left of the box; GK3 at a mannequin left, GK2 central out front.', 'GK2 volleys for GK1 to catch and GK1 rolls it back; GK3 throws a second ball overarm to GK1; GK2 passes the first ball to GK3 while GK1 throws the second ball to GK2; GK3 plays a ground pass to the near post for GK1 to save.', '8 repetitions', NULL, 'Stay sharp and anticipate each action; visualise the full drill first; servers must time throws and passes to keep the rhythm.', '3 GKs', 3, 3, NULL, NULL, NULL, NULL, true, true, true, NULL, 600),
  ('Overarm throw, high catch and small-goal save', 'goalkeeping', 'unopposed', NULL, 76, 76, 'Chapter 5: Drill 11', 'Maarten Arts', 'Overarm distribution, catching and close-range saves in a smaller goal.', 'Small goal in the box with a mannequin, a second goal to the right; coach behind, GK2 out right, mannequin out left.', 'Coach volleys to GK1 who throws back; coach throws a high ball for GK1 to catch; GK1 throws overarm to GK2, who controls, passes to the coach and runs round the mannequin; the coach passes for GK2 to strike: first into GK1''s hands, then at the top corner.', '4 repetitions', NULL, 'Throw to GK2 with one bounce; feel the difference of covering a smaller goal, like a close-range angled shot in a full goal.', '2-3 GKs + coach', 3, 4, NULL, NULL, NULL, NULL, true, true, true, NULL, 610)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'goalkeeping-elite-training-program-60-proven-drills-ebook-vol-1') b;
INSERT INTO schema_migrations (filename) VALUES ('5005-exercises-book-goalkeeping-elite-training-program-60-proven-drills-ebook-vo.sql') ON CONFLICT DO NOTHING;
COMMIT;
